package com.cpf.education.online.messaging.controller;
import com.cpf.core.api.context.CpfContexts;import com.cpf.education.online.messaging.dto.OrderEventCommand;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.messaging.api.*;import com.cpf.web.api.CpfController;import io.swagger.v3.oas.annotations.Operation;import java.nio.charset.StandardCharsets;import java.util.Map;import org.springframework.web.bind.annotation.*;
/** 메시징 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfController @RequestMapping("/edu/online/orders") public class OrderEventController {private final CpfMessagingTemplate messaging;public OrderEventController(CpfMessagingTemplate m){messaging=m;}@PostMapping @Operation(operationId="EDU_ORDER_EVENT_PUBLISH",summary="Messaging·비동기 거래") @CpfOnlineTransaction(operationId="EDU_ORDER_EVENT_PUBLISH",name="Messaging·비동기 거래",description="CPF Messaging이 Context·correlation·idempotency를 전파하고 Listener Runtime이 retry/DLQ/duplicate 정책을 적용한다.") public CpfBrokerPublishResult send(@RequestBody OrderEventCommand c){return messaging.send(new CpfBrokerPublishRequest(c.messageId(),"edu.member.changed",c.memberId(),c.payload().getBytes(StandardCharsets.UTF_8),"application/json","EDU","EXS",c.idempotencyKey(),Map.of(),Map.of("correlationId",CpfContexts.transactionId())));}}
